INSERT INTO categorias (nome, descricao, id) VALUES ('Legislação de Trânsito', 'Regras de circulação e normas do Código de Trânsito Brasileiro.', 1);
INSERT INTO categorias (nome, descricao, id) VALUES ('Sinalização de Trânsito', 'Significado de placas, semáforos e marcas viárias.', 2);
INSERT INTO categorias (nome, descricao, id) VALUES ('Direção Defensiva', 'Como prever e evitar acidentes de trânsito.', 3);
INSERT INTO categorias (nome, descricao, id) VALUES ('Primeiros Socorros', 'Condutas básicas em caso de acidente de trânsito.', 4);
INSERT INTO categorias (nome, descricao, id) VALUES ('Mecânica Básica', 'Cuidados e verificações básicas do veículo.', 5);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (1, 'A Lei Seca adota tolerância zero: qualquer concentração de álcool no organismo do condutor já é considerada infração, independentemente da quantidade ingerida. Não existe uma ''dose permitida'' antes de dirigir.', 'https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm', 1);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (1, 'Em cruzamentos sem sinalização (sem placa ou semáforo), a regra geral de preferência é: tem prioridade de passagem o veículo que vier pela direita do condutor. Essa regra vale para a maioria dos cruzamentos comuns em áreas urbanas.', 'https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm', 2);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (1, 'O uso do cinto de segurança é obrigatório para todos os ocupantes do veículo, em qualquer banco — motorista, passageiro da frente e passageiros de trás. Trafegar sem o cinto é considerado infração grave.', 'https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm', 3);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (1, 'Limites de velocidade sem sinalização (CTB, art. 61): vias de trânsito rápido 80 km/h, arteriais 60 km/h, coletoras 40 km/h e locais 30 km/h. Em rodovias de pista dupla o limite para automóveis é 110 km/h e, em pista simples, 100 km/h.', 'https://www.planalto.gov.br/ccivil_03/leis/l9503compilado.htm', 4);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (2, 'As placas de trânsito são divididas em três grandes grupos, cada um com uma cor e formato próprios: REGULAMENTAÇÃO (circulares, fundo branco, borda vermelha) impõem uma obrigação, proibição ou restrição — como ''Pare'' ou ''Proibido Estacionar''. ADVERTÊNCIA (triangulares, fundo amarelo) alertam sobre um perigo à frente, como uma curva ou pista escorregadia. INDICAÇÃO (retangulares, fundo azul ou verde) informam direções, distâncias e serviços disponíveis.', 'https://www.gov.br/transportes/pt-br/assuntos/transito/senatran/manuais-brasileiros-de-sinalizacao-de-transito', 5);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (2, 'A placa ''PARE'' (octogonal, vermelha) é a única que exige parada completa e obrigatória do veículo antes de prosseguir, mesmo que a via esteja livre no momento.', 'https://www.gov.br/transportes/pt-br/assuntos/transito/senatran/manuais-brasileiros-de-sinalizacao-de-transito', 6);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (2, 'Semáforos amarelos piscantes (intermitentes) indicam que o condutor deve reduzir a velocidade e seguir com atenção redobrada — é diferente do amarelo fixo, que antecede o vermelho e pede que o condutor pare, caso ainda seja possível fazê-lo com segurança.', 'https://www.gov.br/transportes/pt-br/assuntos/transito/senatran/manuais-brasileiros-de-sinalizacao-de-transito', 7);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (2, 'A ordem de prioridade da sinalização (CTB, art. 89) é: 1º ordens do agente de trânsito, 2º indicações do semáforo, 3º demais sinais (placas e marcas) e 4º normas gerais de circulação.', 'https://www.gov.br/transportes/pt-br/assuntos/transito/senatran/manuais-brasileiros-de-sinalizacao-de-transito', 8);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (3, 'Direção defensiva é a forma de dirigir que busca prevenir acidentes, mesmo diante de condições adversas ou de erros cometidos por outros condutores, pedestres ou ciclistas. Não basta seguir as regras: é preciso antecipar riscos.', 'https://www.detraneduca.pr.gov.br/Pagina/Direcao-defensiva', 9);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (3, 'A distância de segurança em relação ao veículo da frente não deve ser fixa — ela precisa aumentar conforme a velocidade do trânsito e as condições da via (chuva, pista molhada, pouca visibilidade). Quanto maior a velocidade, maior o espaço necessário para frear com segurança.', 'https://www.detraneduca.pr.gov.br/Pagina/Direcao-defensiva', 10);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (3, 'Cansaço e sono são fatores de risco tão sérios quanto o álcool na direção. Ao sentir sinais de sonolência, a orientação é parar em local seguro e descansar — abrir o vidro ou aumentar o som não resolvem o problema, só mascaram os sintomas por pouco tempo.', 'https://www.detraneduca.pr.gov.br/Pagina/Direcao-defensiva', 11);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (4, 'Ao se deparar com um acidente de trânsito, a primeira atitude não é mover a vítima, e sim sinalizar o local (para evitar novos acidentes) e acionar o socorro especializado pelo número 192 (SAMU).', 'https://bvsms.saude.gov.br/bvs/publicacoes/manual_primeiros_socorros.pdf', 12);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (4, 'Vítimas conscientes devem, sempre que possível, ser mantidas no local onde foram encontradas, com o mínimo de movimentação, até a chegada do socorro — mover uma vítima de forma incorreta pode agravar lesões na coluna que não são visíveis a olho nu.', 'https://bvsms.saude.gov.br/bvs/publicacoes/manual_primeiros_socorros.pdf', 13);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (4, 'O método PAS resume a sequência básica de atendimento em uma emergência: Proteger (sinalizar o local e evitar novos acidentes), Alertar (acionar o socorro) e Socorrer (prestar os primeiros cuidados dentro do que o condutor souber fazer com segurança, sem se colocar em risco).', 'https://bvsms.saude.gov.br/bvs/publicacoes/manual_primeiros_socorros.pdf', 14);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (5, 'O painel do veículo tem luzes indicadoras que avisam sobre problemas antes que eles se tornem graves. A luz de óleo, por exemplo, indica problema na pressão ou no nível do óleo do motor e não deve ser ignorada.', 'https://escola.detran.rs.gov.br/wp-content/uploads/2022/11/funcionamento_veiculo.pdf', 15);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (5, 'Pane seca é o termo usado quando o veículo para de funcionar por falta de combustível — é uma das causas mais comuns (e mais evitáveis) de veículos parados no acostamento.', 'https://escola.detran.rs.gov.br/wp-content/uploads/2022/11/funcionamento_veiculo.pdf', 16);
INSERT INTO materiais (categoria_id, conteudo, url, id) VALUES (5, 'Se o motor superaquecer (''ferver''), o procedimento correto é parar em local seguro, desligar o motor e aguardar esfriar antes de sequer tentar abrir o radiador — abrir um radiador quente pode causar queimaduras sérias pela pressão e pelo vapor liberado.', 'https://escola.detran.rs.gov.br/wp-content/uploads/2022/11/funcionamento_veiculo.pdf', 17);
